before.code:
function truncate(el, suffix) {
  const full = (el.dataset.full ??= el.textContent);
  el.textContent = full;
  let n = full.length;
  while (el.scrollWidth > el.clientWidth && n > 0) {
    el.textContent = full.slice(0, --n) + suffix;
  }
}
truncate(title, ' ⋯ 더보기');
addEventListener('resize', () => truncate(title, ' ⋯ 더보기'));

after.code:
.title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: " ⋯ 더보기";
}
